# Test the w-string as a TELETHON StringSession generated by an OLDER telethon
# that used base64 WITHOUT urlsafe (- and _ present though...).
# OR as Kurigram/Pyrogram: pyrogram session = b64 of "dc_id|auth_key|user_id" style? No,
# pyrogram uses its own: version + b64(struct).
#
# PYROGRAM v2 SESSION FORMAT:
#   VERSION_BYTE (e.g. 2) + packed(dc_id int32, api_id int32, test_mode bool, auth_key 256B,
#   user_id int64, is_bot bool) -> b64url, prefix like 'BAAy...' BQ etc.
# Pyrogram strings typically start with 'B' + 'Q'/string... not 'w'.
#
# Let's brute force interpretations: maybe 'w' IS the version byte for a modified lib.
# Decode body as >B4sH256s after skipping 'w':
import base64, struct, ipaddress
v = open('/opt/tg-watcher/.env').read().split('TG_SESSION_STRING=')[1].split()[0]
body = base64.urlsafe_b64decode(v[1:] + '=' * (-len(v[1:]) % 4))
print('body bytes:', len(body))
if len(body) >= 263:
    dc_id, ip, port, key = struct.unpack('>B4sH256s', body[:263])
    print('dc', dc_id, 'ip', ipaddress.ip_address(ip), 'port', port, 'keyHead', key[:4].hex())
    print('leftover bytes:', len(body) - 263)
else:
    # 251 bytes: maybe NO auth key (empty session): >B4sH = 7 bytes -> check
    dc_id, ip, port = struct.unpack('>B4sH', body[:7])
    print('no-key parse: dc', dc_id, 'ip', ipaddress.ip_address(ip), 'port', port)
    print('leftover:', len(body)-7, 'head', body[7:15].hex())
